import java.io.*;
import java.nio.file.*;
import java.util.*;

public class ConfigReader {
    public Properties loadConfig(String path) throws IOException {
        var props = new Properties();

        // BufferedReader automatically closed after try block
        try (var reader = Files.newBufferedReader(Path.of(path))) {
            props.load(reader);
            return props;
        } // close() called here automatically, even if load() throws
    }

    public void writeLog(String message) throws IOException {
        // FileWriter automatically closed, no manual cleanup needed
        try (var writer = new FileWriter("app.log", true)) {
            writer.write(message + "\n");
        } // close() guarantees flush and file handle release
    }
}

