import java.io.*;
import java.nio.file.*;

public class FileProcessor {
    public void copyWithLogging(String source, String dest, String logFile) throws IOException {
        // Three resources: input, output, log—all closed automatically
        try (var reader = Files.newBufferedReader(Path.of(source));
             var writer = Files.newBufferedWriter(Path.of(dest));
             var logger = new FileWriter(logFile, true)) {

            String line;
            int lineCount = 0;

            while ((line = reader.readLine()) != null) {
                writer.write(line);
                writer.newLine();
                lineCount++;
            }

            logger.write("Copied " + lineCount + " lines\n");

        } // Closes in reverse: logger, writer, reader
          // Each close() guaranteed even if previous close() throws
    }
}

