public class SuppressedExceptions {
    static class Noisy implements AutoCloseable {
        public void use()   { throw new RuntimeException("body failed"); }
        public void close() { throw new RuntimeException("close failed"); }
    }

    public static void main(String[] args) {
        try (Noisy n = new Noisy()) {
            n.use();
        } catch (Exception e) {
            System.out.println(e.getMessage());            // body failed (primary)
            for (Throwable s : e.getSuppressed()) {
                System.out.println("suppressed: " + s.getMessage()); // close failed
            }
        }
    }
}
