import java.sql.*;

public class TransactionScope implements AutoCloseable {
    private final Connection connection;
    private boolean committed = false;

    public TransactionScope(Connection conn) throws SQLException {
        this.connection = conn;
        connection.setAutoCommit(false);
    }

    public void commit() throws SQLException {
        connection.commit();
        committed = true; // mark as successful
    }

    @Override
    public void close() throws SQLException {
        if (!committed) {
            connection.rollback(); // auto-rollback if commit wasn't called
        }
        connection.setAutoCommit(true);
    }

    // Usage in service layer
    public void transferFunds(long fromId, long toId, double amount) throws SQLException {
        try (var tx = new TransactionScope(getConnection())) {
            debitAccount(fromId, amount);
            creditAccount(toId, amount);
            tx.commit(); // explicit success
        } // rollback happens automatically if any step throws
    }
}

import java.io.*;
import java.sql.*;

public class ResourceManager {
    // Java 9+ style: use existing variables directly
    public void processStream(InputStream input) throws IOException {
        // 'input' is effectively final (method parameter, never reassigned)
        try (input) { // Java 9+: reference existing variable
            var data = input.readAllBytes();
            process(data);
        } // input.close() called automatically
    }

    // Factory-produced resource example
    public void queryDatabase(ConnectionFactory factory) throws SQLException {
        var connection = factory.createConnection(); // from factory

        try (connection) { // Java 9+: use the existing variable
            var stmt = connection.prepareStatement("SELECT * FROM orders");
            try (stmt) { // can do this for stmt too
                var rs = stmt.executeQuery();
                // process results
            }
        }
    }
}
